            // check if there are leftovers in next `haystack`
            continue;

        break;
#else
        if (isASCII(data[pos]) && !isAlphaNumericASCII(data[pos]))
        {
            /// Finish current token if any
            if (token_length > 0)
                return true;
            token_start = ++pos;
        }
        else
        {
            /// Note that UTF-8 sequence is completely consisted of non-ASCII bytes.
            ++pos;
            ++token_length;
        }
#endif
